Consider below code fragment:
Test (list, n)
Nodeptr *list;
int n;
{
    Nodeptr p, q;
    int m;
    q = NULL;
    p = *list;
    while (p != NULL)
      if(p -> info == n)
      {
        p = p -> next;
        if(q == NULL)
        {
          freenode(*list);
          *list = p;
        }
        else
          deleteafter(q, &m);
      }
      else
      {
        q = p;
        p = p -> next;
      }
}
deleteafter (q, & m) next node after q will be deleted and deleted data will be stored in m. freenode (*list) frees a node. Then what is the function of Test?

